'use client';

import { useState } from 'react';

import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { PRESS_LEAD_MS, usePress } from '@/registry/ndeko/lib/demonstration';
import { QuoteIcon } from '@/registry/ndeko/lib/icons';
import { Badge } from '@/registry/ndeko/ui/badge';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { QUOTES, SECTION, type ThemeChoice } from './data';
import { QuoteCard } from './quote-card';
import { spokenLineOf, ThemePicker } from './theme-picker';

const DEMO_THEMES: ThemeChoice[] = ['replies', 'handoffs', 'setup', 'all'];

const FIRST_PICK_MS = 2200;

const READ_MS = 3400;

const LOOP_AFTER_MS = 2600;

function delayBeforePick(index: number) {
  if (index === 0) {
    return FIRST_PICK_MS;
  }
  return READ_MS;
}

export default function Testimonials01() {
  const [theme, setTheme] = useState<ThemeChoice>('all');
  const [message, setMessage] = useState('');
  const { pressed, press } = usePress<ThemeChoice>();

  const steps = DEMO_THEMES.flatMap((choice, index) => [
    { after: delayBeforePick(index), run: () => press(choice) },
    { after: PRESS_LEAD_MS, run: () => setTheme(choice) },
  ]);
  const { ref } = useAutoplay<HTMLElement>(steps, {
    loopAfter: LOOP_AFTER_MS,
    onReset: () => setTheme('all'),
  });

  function pick(choice: ThemeChoice) {
    setTheme(choice);
    setMessage(spokenLineOf(choice));
  }

  return (
    <section ref={ref} className='@container'>
      <div className='mx-auto flex max-w-6xl flex-col gap-10 px-4 py-16 @2xl:px-6 @2xl:py-24 @5xl:px-8'>
        <header className='flex max-w-2xl flex-col gap-3'>
          <p className='text-primary-ink flex items-center gap-1.5 text-[13px] font-medium'>
            <QuoteIcon className='size-4' />
            {SECTION.label}
          </p>
          <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
            {SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {SECTION.lead}
          </p>
        </header>
        <div className='flex flex-col gap-5'>
          <div className='flex flex-wrap items-center justify-between gap-3'>
            <ThemePicker value={theme} pressed={pressed} onValueChange={pick} />
            <Badge variant='secondary'>Sample quotes</Badge>
          </div>
          <div className='columns-1 gap-4 *:mb-4 *:break-inside-avoid @xl:columns-2 @4xl:columns-3'>
            {QUOTES.map((quote) => (
              <QuoteCard key={quote.id} quote={quote} theme={theme} />
            ))}
          </div>
        </div>
      </div>
      <LiveRegion message={message} />
    </section>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import { QUOTES, THEMES, type Theme, type ThemeChoice } from './data';

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

type Choice = {
  id: ThemeChoice;
  label: string;
  count: number;
};

function countOf(choice: ThemeChoice) {
  if (choice === 'all') {
    return QUOTES.length;
  }
  const matching = QUOTES.filter((quote) => quote.theme === choice);
  return matching.length;
}

function choiceOfTheme(theme: Theme): Choice {
  return { id: theme.id, label: theme.label, count: countOf(theme.id) };
}

const ALL_CHOICE: Choice = {
  id: 'all',
  label: 'All quotes',
  count: QUOTES.length,
};

const THEME_CHOICES = THEMES.map((theme) => choiceOfTheme(theme));

const CHOICES: Choice[] = [ALL_CHOICE, ...THEME_CHOICES];

function quotesWordOf(count: number) {
  if (count === 1) {
    return '1 quote';
  }
  return `${count} quotes`;
}

export function spokenLineOf(choice: ThemeChoice) {
  const count = countOf(choice);
  if (choice === 'all') {
    return `All ${quotesWordOf(count)}`;
  }
  const theme = THEMES.find((candidate) => candidate.id === choice);
  const subject = theme?.spoken ?? '';
  return `${quotesWordOf(count)} about ${subject}`;
}

type ThemePickerProps = {
  value: ThemeChoice;
  pressed: ThemeChoice | null;
  onValueChange: (choice: ThemeChoice) => void;
};

export function ThemePicker({
  value,
  pressed,
  onValueChange,
}: ThemePickerProps) {
  const pressedValues = [value];

  /** Pressing the chosen theme again would leave nothing pressed: the choice stays. */
  function change(nextValues: unknown[]) {
    const [nextValue] = nextValues;
    const choice = CHOICES.find((candidate) => candidate.id === nextValue);
    if (choice) {
      onValueChange(choice.id);
    }
  }

  return (
    <ToggleGroup
      aria-label='Show the quotes about'
      value={pressedValues}
      onValueChange={change}
      travel
      size='sm'
      indicatorClassName={THUMB}
      className='bg-foreground/[0.05] flex-wrap rounded-lg p-0.5'
    >
      {CHOICES.map((choice) => (
        <ToggleGroupItem
          key={choice.id}
          value={choice.id}
          className={cn(
            'h-7 gap-1.5 rounded-md px-2.5 text-xs',
            pressedQuietOf(pressed === choice.id)
          )}
        >
          {choice.label}
          <span className='text-muted-foreground tabular-nums'>
            {choice.count}
          </span>
        </ToggleGroupItem>
      ))}
    </ToggleGroup>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';

import type { Quote, QuotePart, ThemeChoice } from './data';

type Emphasis = 'even' | 'marked' | 'quiet';

function emphasisOf(quote: Quote, theme: ThemeChoice): Emphasis {
  if (theme === 'all') {
    return 'even';
  }
  if (quote.theme === theme) {
    return 'marked';
  }
  return 'quiet';
}

const TEXT_CLASS: Record<Emphasis, string> = {
  even: 'text-foreground',
  marked: 'text-foreground',
  quiet: 'text-muted-foreground',
};

/**
 * A flat tint drawn as an image, so its size can grow from the start of the phrase on every line it
 * wraps to. The browser paints a mark yellow by default: its own colour is cleared.
 */
const PHRASE =
  'from-primary/15 to-primary/15 -mx-0.5 rounded-[3px] bg-transparent bg-linear-to-r bg-no-repeat box-decoration-clone px-0.5 font-medium transition-[background-size,color] duration-500 ease-(--ease-out-strong) motion-reduce:transition-colors';

const PHRASE_CLASS: Record<Emphasis, string> = {
  even: 'text-primary-ink [background-size:0%_100%]',
  marked: 'text-primary-ink [background-size:100%_100%]',
  quiet: 'text-muted-foreground [background-size:0%_100%]',
};

type QuotePartViewProps = {
  part: QuotePart;
  emphasis: Emphasis;
};

function QuotePartView({ part, emphasis }: QuotePartViewProps) {
  if (part.kind === 'phrase') {
    return (
      <mark className={cn(PHRASE, PHRASE_CLASS[emphasis])}>{part.text}</mark>
    );
  }
  if (part.kind === 'brand') {
    return (
      <span className='whitespace-nowrap'>
        <BrandTile brand={part.brand} size='sm' className='me-1 align-[-3px]' />
        {part.text}
      </span>
    );
  }
  return part.text;
}

type QuoteCardProps = {
  quote: Quote;
  theme: ThemeChoice;
};

export function QuoteCard({ quote, theme }: QuoteCardProps) {
  const emphasis = emphasisOf(quote, theme);
  const { person } = quote;

  return (
    <figure className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] flex flex-col gap-5 rounded-xl p-5 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
      <blockquote
        className={cn(
          'text-sm leading-6 text-pretty transition-colors duration-300',
          TEXT_CLASS[emphasis]
        )}
      >
        <p>
          {quote.parts.map((part, index) => (
            <QuotePartView key={index} part={part} emphasis={emphasis} />
          ))}
        </p>
      </blockquote>
      <figcaption className='flex items-center gap-3'>
        <Avatar seed={person.name} />
        <span className='flex min-w-0 flex-1 flex-col'>
          <span className='truncate text-[13px] font-medium'>
            {person.name}
          </span>
          <span className='text-muted-foreground truncate text-xs'>
            {person.role}, {person.company}
          </span>
        </span>
        <CompanyMark seed={person.company} />
      </figcaption>
    </figure>
  );
}

import type { BrandSlug } from '@/registry/ndeko/lib/brand-logos';

export type ThemeId = 'replies' | 'handoffs' | 'setup';

export type ThemeChoice = ThemeId | 'all';

export type Theme = {
  id: ThemeId;
  label: string;
  spoken: string;
};

/** A quote is written in parts: the phrase is the one its theme lights, a brand part wears its real mark. */
export type QuotePart =
  | { kind: 'text'; text: string }
  | { kind: 'phrase'; text: string }
  | { kind: 'brand'; brand: BrandSlug; text: string };

export type Person = {
  name: string;
  role: string;
  company: string;
};

export type Quote = {
  id: string;
  theme: ThemeId;
  parts: QuotePart[];
  person: Person;
};

